// Her kayıt: gündelik bağlam → görsel deney → gerekçeli örnek → koşullu kısa yol.
import { DIVISION_EXPLORATIONS } from './division-explorations.js';
const lesson = (title, story, terms, experiment, example, steps, tip, trap, transfer, expert) =>
  ({ title, story, terms, experiment, example, steps, tip, trap, transfer, expert });

export const EXPLORATIONS = {
  ...DIVISION_EXPLORATIONS,
  'temel-kavramlar': lesson(
    'Sayıların bir adresi var',
    'Bir markette 3 ekmek sayarsın; hava sıcaklığı −3 derece olabilir; yarım ekmek ise 1/2 ile anlatılır. Bu üç ihtiyaç aynı sayı ailesine sığmaz. Sayı kümeleri, hangi sayılarla çalışabildiğimizi söyleyen adreslerdir.',
    [['Rakam', 'Sayı yazdığımız sembol: 0–9. 12 bir sayıdır, iki rakamla yazılır.'], ['Küme', 'Ortak bir özelliği olan nesneler topluluğu. Bir sayı birden fazla kümeye ait olabilir.'], ['En dar küme', 'Sayıyı içeren en küçük aile; diğer büyük ailelere de üyedir.']],
    'Önce 3’ü, sonra −3’ü ve 1/2’yi seç. İç içe kutularda hangi üyeliklerin kaldığını izle. √9 seçtiğinde kök işareti seni yanıltmasın: önce işlemi yap.',
    '“√9 hangi sayı kümelerine aittir?” sorusunu birlikte çözelim.',
    [['Önce sembolün değerini bul', '$\\sqrt{9}=3$; çünkü $3\\cdot3=9$. Kök işareti, sayının irrasyonel olduğunu tek başına söylemez.'], ['En küçük aileyi bul', '3 bir doğal sayıdır. Burada doğal sayılar 0, 1, 2, … ile başlar.'], ['Büyük aileleri de kontrol et', '3 aynı zamanda tam sayıdır. $3=3/1$ yazılabildiğinden rasyoneldir ve gerçek sayıdır. En dar küme sorulursa yalnız doğal sayılar cevabını veririz.']],
    'Sayı kümesi sorusunda önce sadeleştir, sonra sınıflandır. “En dar küme” ile “ait olduğu kümeler” farklı şeyler ister.',
    '0 doğal ve tam sayıdır; fakat ne pozitif ne negatiftir. “Pozitif tam sayı” koşulunda 0 seçilmez.',
    ['−√16’nın en dar kümesi hangisidir?', 'Tam sayılar', 'Doğal sayılar', 'Önce −√16 = −4. −4 tam sayıdır; negatif olduğu için doğal değildir.'],
    'Tek–çift sorularında çift sayı eşleşen nesneler, tek sayı bir artan nesne demektir. İki tek sayıdaki artanlar eşleşir. “Her zaman” iddiasını bir karşı örnek çürütür; birkaç doğru örnek ise kanıtlamaz.'),
  'sayi-basamaklari': lesson(
    'Aynı rakam, farklı görev',
    'Para sayarken 3 yüzlük, 2 onluk ve 4 birlik toplam 324 eder. Rakamın yanındaki konum, kaç tane birlik temsil ettiğini belirler. Ondalık sistemin gücü, yalnız on sembolle çok büyük sayıları yazabilmesidir.',
    [['Basamak', 'Rakamın sayının içindeki yeri.'], ['Sayı değeri', 'Rakamın kendisi; 324 içindeki 3 için 3.'], ['Basamak değeri', 'Rakam × bulunduğu yerin değeri; aynı 3 için 300.']],
    'Onlar basamağını bir artır. Toplam kaç artıyor? Sonra yüzler basamağını bir artırıp karşılaştır. Kutuların değerleriyle yazılan sayı aynı anda değişir.',
    'Birler basamağı 4, onlar basamağı 2, yüzler basamağı 3 olan sayı kaçtır?',
    [['Her rakamı konumuyla çarp', '3 yüzlük 300, 2 onluk 20, 4 birlik 4 eder.'], ['Parçaları birleştir', '$300+20+4=324$. Rakam toplamı olan 9 ile sayının kendisi olan 324 aynı değildir.'], ['Yer değiştirmeyi farkla kontrol et', '324 → 342 olduğunda 2 onluktan birliğe geçer (−18), 4 birlikten onluğa geçer (+36). Net artış 18’dir.']],
    'İki basamaklı $ab$ sayısını $10a+b$ yaz. Tersiyle farkı $9(a-b)$ olur; uzun çıkarma yapmadan farkın 9’un katı olduğunu görürsün.',
    'Yan yana yazılan $ab$, rakam sorusunda $a\\cdot b$ değildir. İlk basamak 0 olursa basamak sayısı düşer.',
    ['47’nin rakamları yer değiştirirse sayı kaç artar?', '27', '3', '74−47=27. Kısa yol: 9×(7−4)=27; rakam farkı tek başına sayı farkı değildir.'],
    '10 ile çarpmak her rakamı bir üst basamağa taşır. Sona c rakamını eklemek bu nedenle 10N+c’dir; başa rakam eklemek ise eski sayının kaç basamaklı olduğuna bağlıdır.'),
  'bolme-bolunebilme': lesson(
    'Bölme, eş gruplar ve artanlar',
    '23 kitabı her kutuda 5 kitap olacak şekilde yerleştir. Dört dolu kutu ve üç artan kitap elde edersin. Bölüm kutu sayısını, kalan henüz bir kutu dolduramayan kitapları anlatır.',
    [['Bölünen', 'Dağıtılan toplam miktar.'], ['Bölen', 'Her eş gruptaki miktar.'], ['Kalan', 'Tam gruplar kurulunca artan miktar; bölenin altında olmalı.']],
    'Kitap sayısını 23’ten 24’e, sonra 25’e çıkar. Beşinci kutunun ne zaman dolduğunu izle. Kalan 5 olduğunda neden artık kalan sayılmadığını açıklamayı dene.',
    '23 sayısının 5 ile bölümünde bölüm ve kalan nedir?',
    [['Aşmadan en yakın katı bul', '$5\\cdot4=20$; $5\\cdot5=25$ toplamı aşar. Bu yüzden 4 tam grup kurabiliriz.'], ['Artanı hesapla', '$23-20=3$. Bu üç kitap beş kitaplık yeni bir kutu oluşturamaz.'], ['Eşitlikle sağlamasını yap', '$23=5\\cdot4+3$. Ayrıca $0\\leq3<5$; kalan koşulu sağlanır.']],
    'Kalan sorusunda sayıyı $bq+r$ yaz. Çok büyük sayının tamamını hesaplamak yerine ilgili bölenin katlarını çıkarabilirsin.',
    'Bölen ve kalan eşit olamaz: kalan bölen kadar olursa bir tam grup daha vardır. Bölünebilme için kalan tam olarak 0 olmalıdır.',
    ['29 kitabı 6’lı kutulara koyarsak kaç kitap artar?', '5', '4', '6×4=24; 29−24=5. 4 kutu sayısıdır, kalan değildir.'],
    '9 ile bölünebilme rakam toplamından anlaşılır: 10, 100, 1000… sayılarının 9’a bölümünde kalan 1’dir. Bu yüzden her basamaktaki rakam, kalan hesabına kendi değeri kadar katkı yapar.'),
  'ebob-ekok': lesson(
    'Parçalamak mı, buluşturmak mı?',
    '12 cm ve 18 cm’lik iki şeridi hiç artmayacak biçimde eşit ve olabildiğince uzun parçalara ayırmak istiyorsun. İki şeritte de işe yarayan parça uzunluğunu arıyoruz. Aynı sayılarla çalışan iki zilin yeniden birlikte çalması ise başka bir sorudur: ortak kat ararız.',
    [['Bölen', 'Bir sayıyı kalansız bölen sayı.'], ['EBOB', 'İki sayının ortak bölenlerinin en büyüğü.'], ['EKOK', 'İki pozitif tam sayının ortak pozitif katlarının en küçüğü.']],
    'Parça uzunluğunu 2, 3, 4 ve 6 yap. İki şeritte de sınırların tam oturduğu uzunlukları bul. En büyük ortak parçayı seçince neden daha az parça oluşuyor?',
    '12 ve 18 cm’lik şeritlerden kesilebilecek en uzun eş parçalar kaç cm’dir?',
    [['İlk şeridi kalansız bölenleri yaz', '12 için 1, 2, 3, 4, 6 ve 12. Bunlar aday parça uzunluklarıdır.'], ['İkinci şeritle ortak olanları seç', '18’in bölenleri 1, 2, 3, 6, 9, 18. Ortak adaylar 1, 2, 3 ve 6’dır.'], ['İstenen büyüklüğü seç ve doğrula', 'En büyük ortak bölen 6. İlk şeritte 2, ikinci şeritte 3 parça olur; toplam 5 parça ve hiç artan yok.']],
    '“Eş parçalara ayır, artmasın, en büyük parça” → EBOB. “Tekrar aynı anda, ilk ortak zaman” → EKOK. Önce neyin küçük veya büyük istendiğini belirle.',
    '“En az” kelimesini görür görmez EKOK seçme. En az parça sayısı için parça boyu en büyük olmalıdır; bu bir EBOB sorusudur.',
    ['4 ve 6 dakikada bir çalan iki zil şimdi birlikte çaldı. Kaç dakika sonra yeniden birlikte çalar?', '12', '2', '4’ün katları 4, 8, 12; 6’nın katları 6, 12. İlk ortak pozitif zaman 12; EBOB olan 2 bir buluşma zamanı değildir.'],
    'İki pozitif tam sayı için EBOB(a,b)×EKOK(a,b)=a×b. Bu bağıntıyı üç sayıya doğrudan uygulayamazsın. Ortak böleni ayırıp kalan çarpanların aralarında asal olmasına bakmak soruyu hızlandırır.'),
  'rasyonel-sayilar': lesson(
    'Payda parçanın boyunu söyler',
    'Aynı boydaki bir ekmeğin yarısıyla üçte birini toplayalım. “Bir parça + bir parça = iki parça” demek yetmez; parçalar aynı boyda değil. İkisini de altıda birlik dilimlere çevirince ölçü birimimiz eşit olur.',
    [['Payda', 'Bir bütünün kaç eş parçaya ayrıldığını söyler.'], ['Pay', 'Bu parçalardan kaç tanesini aldığımızı söyler.'], ['Denk kesir', 'Yazılışı farklı, değeri aynı kesir; kesmek miktarı değiştirmez.']],
    'Yarımın dilimlerini 2’den 6’ya çıkar. Boyanan uzunluk değişmeden dilim sayısının arttığını gör. İkinci şeritte üçte birin aynı birimle kaç dilim olduğunu say.',
    '$1/2+1/3$ neden $2/5$ değildir?',
    [['Aynı bütünü esas al', 'İki şerit de aynı uzunluğu temsil ediyor. Farklı büyüklükte iki pastanın dilimlerini doğrudan karşılaştıramayız.'], ['Parçaları eş boyda yaz', '$1/2=3/6$ ve $1/3=2/6$. Pay ile paydayı aynı sayıyla çarpmak miktarı korur.'], ['Aynı parçaları say', '3 altıda birlik + 2 altıda birlik = 5 altıda birlik: $5/6$. Toplam 1/2’den büyük ve 1’den küçük; sonuç mantıklı.']],
    'Toplama ve çıkarmada önce ortak parça boyu: ortak payda. Çarpmada ise çapraz sadeleştir; payda eşitlemek zorunda değilsin.',
    'Pay ve paydayı ayrı ayrı toplamak parçaların boyunu değiştirir. Paylar eşit ve pozitifse, daha büyük pozitif payda daha küçük kesir verir: 1/8, 1/4’ten küçüktür. Bu karşılaştırmada payların aynı olması şartını unutma.',
    ['1/4 + 1/2 kaçtır?', '3/4', '2/6', 'Yarımı iki çeyrek olarak yaz: 1/4+2/4=3/4. Üç eş çeyrek parça elde edersin.'],
    'Pozitif kesirleri karşılaştırırken çapraz çarpma ortak paydayla karşılaştırmanın kısa yoludur. Negatif sayılarda ve işareti bilinmeyen paydalarda önce işaretleri belirle; eşitsizliği rastgele çarpma.'),
  'uslu-ifadeler': lesson(
    'Aynı çarpanı tekrar tekrar kullanmak',
    'Bir dosyanın her turda iki kopyası oluşturulursa miktar 2, 4, 8, 16 diye büyür. Her tur 2 eklemiyoruz; var olan miktarın iki katını alıyoruz. Üs, bu tekrarlı çarpmayı kısa yazar.',
    [['Taban', 'Tekrar çarpılan sayı.'], ['Üs', 'Pozitif tam sayı olduğunda tabanın kaç kez çarpan yazıldığını söyler.'], ['Çarpan', 'Bir çarpma işleminin içindeki sayılardan biri.']],
    'Üssü birer birer artır. Her adımda sonucun kaç katına çıktığını izle. Sonra üssü 1’den 0’a indir: düzenin bozulmaması için sonuç neden 1 olmalı?',
    '$2^3\\cdot2^2$ işlemini kural ezberlemeden yapalım.',
    [['Üsleri aç', '$2^3=2\\cdot2\\cdot2$, $2^2=2\\cdot2$. Üs, “üçle çarp” demek değildir.'], ['Çarpanları bir araya getir', 'Toplam beş tane 2 çarpanı var: $2\\cdot2\\cdot2\\cdot2\\cdot2=2^5$.'], ['Sonucu ve kuralı çıkar', '$2^5=32$. Aynı tabanlı kuvvetler çarpılırken üsler toplanır; çünkü çarpan sayıları birleşir.']],
    'İlk iş tabanları eşitle: $8^2=(2^3)^2=2^6$. Aynı taban görünür olduğunda çarpma, bölme ve karşılaştırma çok kısalır.',
    '$2^3+2^2$, $2^5$ değildir. Toplamada çarpan listeleri birleşmez; burada 8+4=12 olur. Üs toplama kuralı çarpma içindir.',
    ['3² · 3³ kaç tane 3 çarpanı içerir?', '5', '6', 'İlkinde 2, ikincisinde 3 tane 3 var; birlikte 5. Üslerin çarpılması, bir kuvvetin tekrar kuvveti alınırken kullanılır.'],
    'Sıfırdan farklı a için her bir üs azaltma a’ya bölmektir: a², a, 1, 1/a… Bu örüntü a⁰=1 ve a⁻¹=1/a kurallarının nedenini verir. 0⁰ için bu çıkarım geçerli değildir.'),
  'koklu-ifadeler': lesson(
    'Alanı biliyorsan kenarı bul',
    'Alanı 36 metrekare olan kare bir odanın bir kenarı 6 metredir; çünkü 6×6=36. Karekök, bu çarpımı geriye doğru sorar. 36’yı ikiye bölmek kenarı vermez: alan ile uzunluk farklı büyüklüklerdir.',
    [['Karekök', 'Karesi verilen sayıya eşit olan negatif olmayan sayı.'], ['Tam kare', 'Bir tam sayının karesi: 0, 1, 4, 9, 16…'], ['Kök dışına çıkarma', 'Kök içindeki tam kare çarpanın kenar karşılığını almak.']],
    'Karenin kenarını değiştir; küçük birim karelerin toplamını say. Kenar 2 katına çıkınca alanın neden 4 katına çıktığını şekilden gör.',
    '$\\sqrt{72}$ nasıl sadeleşir?',
    [['İçeride tam kare çarpan ara', '$72=36\\cdot2$. 36’nın karekökünü biliyoruz; 2 kök içinde kalacak.'], ['Karekökleri ayır', '$\\sqrt{36\\cdot2}=\\sqrt{36}\\cdot\\sqrt2=6\\sqrt2$. Çarpanlar negatif olmadığı için bu ayırma geçerli.'], ['Karesini alıp doğrula', '$(6\\sqrt2)^2=36\\cdot2=72$. Yaklaşık değer de 8 ile 9 arasındadır; çünkü 64<72<81.']],
    'Kök içinde en büyük tam kare çarpanı ara. Toplamadan önce sadeleştir: $\\sqrt8+\\sqrt{18}=2\\sqrt2+3\\sqrt2=5\\sqrt2$.',
    '$\\sqrt{a+b}$ genel olarak $\\sqrt a+\\sqrt b$ değildir. Örneğin √(9+16)=5 ama 3+4=7.',
    ['√50’nin sadeleşmiş hâli nedir?', '5√2', '25√2', '50=25×2; √25=5. 25 dışarı aynı değerle değil, kareköküyle çıkar.'],
    '$\\sqrt{x^2}=|x|$; doğrudan x yazamayız. x=−3 için kök 3 verir. Karekök sembolünün negatif olmayan değeri seçmesi, denklemin iki kökü olmasından farklıdır.'),
  'birinci-derece-denklemler': lesson(
    'Denklem bir dengeyi anlatır',
    'İki aynı kutu ve 3 birimlik ağırlık, 11 birimlik ağırlığı dengeliyor. Kutuların her birinin ağırlığına x diyelim. “2x+3=11” bu durumun kısa yazımıdır. Bilinmeyen bir şeyin adı olması, ona sayı gibi davranamayacağımız anlamına gelmez.',
    [['Bilinmeyen', 'Henüz değerini bilmediğimiz miktar; burada bir kutunun ağırlığı.'], ['Eşitlik', 'İki tarafın aynı değeri taşıdığını söyler.'], ['Ters işlem', 'Yapılmış işlemi geri alan işlem; +3’ü −3 geri alır.']],
    'Terazinin iki tarafından aynı miktarı çıkar. Denge korunuyor mu? Sonra kalan iki eş kutunun toplamını iki eş paya böl. “Karşıya atma” sözünün arkasındaki gerçek işlemi gör.',
    '$2x+3=11$ denklemini çözelim.',
    [['Kutuların yanındaki fazlalığı kaldır', 'İki taraftan 3 çıkar: $2x+3-3=11-3$, yani $2x=8$. Yalnız sol tarafı değiştirirsen eşitlik bozulur.'], ['Bir kutuyu bul', 'İki eş kutu 8 ise bir kutu 4’tür. Her iki tarafı 2’ye böl: $x=4$.'], ['Başlangıçta yerine koy', '$2\\cdot4+3=11$. Bulduğumuz değer ilk cümleyi doğru yaptığı için çözümdür.']],
    'Önce parantezleri aç, benzer terimleri topla; sonra bilinmeyeni yalnız bırak. Sayılar büyükse işlemi bitirmeden ortak çarpanları sadeleştir.',
    '“Karşıya geçince işaret değişir” bir sihir değildir; iki tarafa aynı toplama/çıkarma yapılmasının kısaltmasıdır. Çarpanı geçirirken işaret değil, ters işlem değişir.',
    ['3x+2=14 ise x kaçtır?', '4', '16/3', 'Önce iki taraftan 2 çıkar: 3x=12. Sonra 3’e böl: x=4. Sağ tarafa 2 eklemek, soldaki +2’yi yok etmez.'],
    'Bir denklemi sıfır olabilecek ifadeyle bölersen çözüm kaybedebilirsin. Örneğin x(x−2)=0’da x’e bölmek x=0 çözümünü siler. Önce böldüğün ifadenin sıfır olup olmadığını ayır.'),
  'esitsizlikler': lesson(
    'Sayı doğrusunda yönü korumak',
    'Asansördeki yük en fazla 400 kg olmalıdır. Burada tek bir doğru ağırlık aramayız; 400’ü aşmayan bütün ağırlıklar uygundur. Eşitsizlik, bu izin verilen aralığı anlatır.',
    [['< ve >', 'Kesin küçük ve kesin büyük; sınır dâhil değildir.'], ['≤ ve ≥', 'Eşitlik de mümkündür; sınır dâhildir.'], ['Çözüm kümesi', 'Koşulu sağlayan bütün değerler.']],
    'Sayı doğrusunda −2 ve 3’ün yerlerini gör. İkisini de −1 ile çarpınca yerlerinin nasıl ters döndüğünü izle. İşaret değiştirme kuralının nedeni bu yansımadır.',
    '$-2x<6$ eşitsizliğini çözelim.',
    [['Bilinmeyenin katsayısını belirle', 'x, −2 ile çarpılmış. x’i yalnız bırakmak için iki tarafı −2’ye böleceğiz.'], ['Negatif bölmenin yönü çevirdiğini kullan', '$x>-3$. Sayı doğrusunda yansımayla küçük olan büyük tarafa geçtiğinden < işareti > olur.'], ['Bir içeriden, bir dışarıdan değer dene', 'x=0 için 0<6 doğru; x=−4 için 8<6 yanlış. Böylece −3’ün sağını seçtiğimizi doğrularız.']],
    'Toplama/çıkarma yönü değiştirmez. Negatifle çarpma/bölme yönü değiştirir. İşareti bilinmeyen ifadeyle çarpmadan önce durumları ayır.',
    'Sınırdaki değer otomatik olarak çözüme girmez. x>−3 için −3 alınamaz; x≥−3 için alınabilir.',
    ['−3x ≥ 12 nasıl sadeleşir?', 'x ≤ −4', 'x ≥ −4', 'Her iki tarafı negatif −3’e bölüyoruz; yön döner. x=−5 kontrolü: 15≥12 doğrudur.'],
    'Çarpım ve bölüm eşitsizliklerinde kökler ve tanımsız noktalar sayı doğrusunu aralıklara böler. Her aralıktan tek bir örnekle işaret bulunabilir; paydanın sıfır olduğu noktalar hiçbir zaman alınmaz.'),
  'mutlak-deger': lesson(
    'Yönü değil, uzaklığı ölç',
    'Bir okulun 3 km doğusundaki ev ile 3 km batısındaki ev okula aynı uzaklıktadır. Konum için +3 ve −3 kullanabiliriz; yol uzunluğu ise ikisi için de 3’tür. Mutlak değer bu yön bilgisini uzaklığa dönüştürür.',
    [['|x|', 'x’in sıfıra uzaklığı.'], ['|x−a|', 'x ile a arasındaki uzaklık.'], ['Uzaklık', 'Negatif olamaz; aynı noktadaysan sıfırdır.']],
    'Noktayı merkezin sağına ve soluna taşı. Aynı uzaklıktaki iki konumun farklı olmasına rağmen sonuçlarının aynı olduğunu izle.',
    '$|x-2|=3$ denklemi hangi noktaları anlatır?',
    [['Merkezi belirle', 'x−2 ifadesi 2’ye göre konumu ölçer. Merkez 0 değil 2’dir.'], ['İki yönü düşün', '2’den 3 birim sağa git: 5. 2’den 3 birim sola git: −1. Uzaklık aynı, yönler farklıdır.'], ['İki çözümü de kontrol et', '$|5-2|=3$ ve $|-1-2|=|-3|=3$. Çözüm kümesi {−1, 5}.']],
    '$|x-a|<r$ (r>0) merkezin r birim yakın çevresidir: $a-r<x<a+r$. “Büyük” uzaklıkta bu aralığın dışını düşün.',
    '|x|=−3 mümkün değildir. Ayrıca |x−2| ifadesini |x|−2 diye açamazsın; önce bütün iç ifadenin işaretine bakılır.',
    ['|x−4|=2 için hangi ikili çözümdür?', '2 ve 6', '−2 ve 2', 'Merkez 4: 4−2=2 ve 4+2=6. −2 ve 2, merkezin 0 olduğu sorunun çözümleridir.'],
    '|x−a|+|x−b|, a≤x≤b iken b−a’dır. İki sabit nokta arasında dolaşırken birine yaklaştığın kadar diğerinden uzaklaşırsın; en küçük toplam bu yüzden bütün aralıkta aynıdır.'),
  'oran-oranti': lesson(
    'Tarifi büyüt, tadı koru',
    'Bir içecek tarifinde 2 bardak öz ve 3 bardak su var. İki kat içecek yapmak için yalnız suyu artırırsan tadı değiştirirsin. Her iki miktarı aynı katsayıyla büyütmek oranı korur.',
    [['Oran', 'İki miktarın bölümle karşılaştırılması.'], ['Orantı', 'İki oranın eşit olması.'], ['Oran sabiti', 'Karşılaştırılan miktarlar değişirken sabit kalan bölüm.']],
    'Tarifin kaç katını hazırladığını değiştir. Öz ile su birlikte büyürken 2/3 oranının sabit kaldığını gözle. Toplam miktarı da ayrıca say.',
    'Öz : su oranı 2 : 3 olan 20 bardak içecekte kaç bardak öz vardır?',
    [['Oranları eş parçalar gibi oku', '2 pay öz + 3 pay su = 5 pay içecek. 2/3, özün bütün içeceğe değil suya oranıdır.'], ['Bir payın değerini bul', '20 bardak 5 paya karşılık geliyor: 20÷5=4 bardak bir paydır.'], ['İstenen payı al', 'Öz 2 pay olduğundan 2×4=8 bardak. Su 12 bardak; toplam 20 ve 8/12=2/3.']],
    'Orantılı paylaştırmada miktarları 2k ve 3k yaz. Toplam verilince 5k üzerinden tek işlemle k bulunur.',
    'Birlikte artan her iki büyüklük doğru orantılı değildir. Doğru orantıda bölüm sabit olmalı; başlangıç ücreti olan taksi tarifesi buna örnek değildir.',
    ['2 : 3 oranındaki 30 bardak karışımda öz miktarı?', '12 bardak', '20 bardak', 'Toplam 5 pay; 30/5=6. Öz 2×6=12. 30×2/3 yapmak, toplamı yanlışlıkla su miktarı sayar.'],
    'Sabit işte aynı verimle çalışan işçi sayısı ve süre ters orantılıdır: işçi×süre sabit. İş miktarı veya verim değişirse bu varsayım bozulur; önce sabit olanı belirle.'),
  'sayi-kesir-problemleri': lesson(
    'Cümleyi küçük işlemlere çevir',
    'Bir bisiklet kiralamada sabit 3 TL ve saat başına 2 TL ödendiğini düşün. Toplam 11 TL ödediğinde süreyi bulmak, bir denklemi günlük hayattan okumaktır. Harf, bilmediğimiz saat sayısının yerini tutar.',
    [['Bütün', 'Kesrini aldığımız başlangıç miktarı.'], ['Kalan', 'Bir işlemden sonra elde bulunan yeni miktar.'], ['Model', 'Cümledeki ilişkiyi sayı, şekil veya denklemle yazmak.']],
    'Saat sayısını değiştir. Saatlik ücret büyürken başlangıç ücretinin sabit kaldığına dikkat et. Hedef toplam 11 olduğunda kaç saat gerektiğini bul.',
    '“Bir sayının 2 katının 3 fazlası 11’dir.” Sayıyı bulalım.',
    [['Cümleyi işlem sırasıyla oku', 'Sayı x; iki katı 2x; bunun 3 fazlası 2x+3. Elde edilen miktar 11’e eşit.'], ['Son yapılanı geri al', '$2x+3=11$ → $2x=8$. Önce eklenen 3’ü çıkarırız.'], ['İlk işlemi de geri al ve dene', '$x=4$. Kontrol: 4’ün iki katı 8, 3 fazlası 11. Cümledeki her koşul doğru.']],
    '“Kalanın yarısı” deniyorsa kesri ilk bütünden değil yeni kalandan al. Bütünü uygun paydaların ortak katı seçmek kesir hesabını azaltabilir.',
    '“Sayının iki katının 3 fazlası” 2x+3; “3 fazlasının iki katı” 2(x+3). Kelimelerin sırası parantezin yerini belirler.',
    ['Bir sayının 3 fazlasının iki katı 14 ise sayı?', '4', '11/2', '2(x+3)=14; önce ikiye böl: x+3=7. Sonra 3 çıkar: x=4.'],
    'Sondan başa yönteminde işlemleri hem ters sıraya çevir hem ters işlemlerini uygula. Bir süreçte ikiye bölüp 5 eklenmişse geri dönüşte önce 5 çıkarıp sonra ikiyle çarparsın.'),
  'yuzde-karisim': lesson(
    'Yüzdeyi bir miktara bağla',
    'Bir meyve suyunun %30’u meyve ise her 100 eş miktarın 30’u meyvedir. Şişenin boyu büyürken oran değişmeyebilir ama içindeki meyve miktarı artar. Etiket oranı söyler; gerçek miktar için bütünü de bilmeliyiz.',
    [['Yüzde', 'Her 100 eş paydan kaçının alındığı.'], ['Referans miktar', 'Yüzdesi hesaplanan bütün.'], ['Saf madde', 'Karışımın içinde takip edilen bileşenin gerçek miktarı.']],
    'Önce toplamı sabit tutup yüzdeyi değiştir. Sonra yüzdeyi sabit tutup toplamı büyüt. Aynı %30’un neden farklı miktarlara karşılık geldiğini gör.',
    '200 gram %30 tuzlu karışımda kaç gram tuz vardır?',
    [['Bütünü açıkça yaz', 'Toplam karışım 200 gram. %30, bu toplamın tuz olan payıdır; suyun yüzdesi değildir.'], ['Yüzdeyi kesre çevir', '$200\\cdot30/100=60$ gram tuz. Kalan 140 gram diğer bileşendir.'], ['Su ekleme durumunu düşün', '100 gram su eklenirse tuz hâlâ 60 gramdır. Toplam 300 olur: 60/300=0,20, yani %20.']],
    'Karışımda yüzdeyi değil saf madde miktarını topla: miktar×oran. Su ekleme gibi sorularda önce neyin değişmediğini bul.',
    '%20 artıp %20 azalmak başlangıca döndürmez: 100→120→96. İkinci yüzde yeni miktardan hesaplanır.',
    ['80 TL’nin %25’i kaç TL’dir?', '20', '25', '%25 bir çeyrektir. 80/4=20. 25 sayısı ancak bütün 100 olduğunda miktarı da gösterir.'],
    'İki farklı oranlı karışımın son oranı, pozitif miktarlar için iki oranın arasında kalır. Sonuç daha çok eklenen karışımın oranına yakın olur; basit ortalama yalnız miktarlar eşitse doğrudur.'),
  'kar-zarar': lesson(
    'Yüzdenin başlangıcını seç',
    'Bir dükkân 80 TL’ye aldığı ürünü 100 TL’ye satıyor. Kâr 20 TL’dir. Ancak bu kârı alış fiyatıyla mı satış fiyatıyla mı karşılaştırdığımız, yüzdeyi değiştirir. Finansal terimleri bilmeden de doğru bütünü seçerek soruyu çözebilirsin.',
    [['Maliyet', 'Ürünün elde edilmesi için verilen tutar.'], ['Kâr', 'Satış fiyatı−maliyet; satış daha yüksekse pozitif.'], ['Kâr oranı', 'Soruda belirtilen referans tutara göre kârın oranı.']],
    'Maliyet 80 TL iken kâr yüzdesini değiştir. Kârın maliyetin üstüne eklendiğini izle. Satış fiyatını tekrar %20 düşürmek başlangıca dönmek mi, önce tahmin et.',
    'Maliyeti 80 TL olan ürün %25 kârla kaç TL’ye satılır?',
    [['Referansı belirle', 'Aksi belirtilmedikçe bu soruda kâr maliyet üzerinden. %25’in bütünü 80 TL.'], ['Kârı bul', '$80\\cdot25/100=20$ TL. Bu sonuç satış değil, maliyetin üzerine eklenecek farktır.'], ['Satışa ulaş ve kontrol et', '80+20=100 TL. Kontrol: (100−80)/80=1/4=%25.']],
    'Maliyete göre %p kârda satış = maliyet×(1+p/100). Satıştan maliyete dönerken aynı çarpana böl; aynı yüzdeyi çıkarmaya çalışma.',
    '100 TL satıştan %25 çıkarıp maliyet 75 diyemezsin. %25 maliyet üzerinden verilmişti; doğru geri dönüş 100/1,25=80.',
    ['120 TL’ye %20 kârla satılan ürünün maliyeti?', '100 TL', '96 TL', 'Maliyet×1,20=120; maliyet=100. Satışın %20’sini çıkarmak farklı bir referans kullanır.'],
    'Ardışık indirimlerde kalan çarpanları çarp. %10 ve ardından %20 indirim: 0,90×0,80=0,72; toplam indirim %28’dir. Oranları toplayıp %30 demek ara tutarı atlar.'),
  'hareket-problemleri': lesson(
    'Hız, her zaman dilimindeki yol',
    'Sabit 60 km/sa hızla giden araç her saatte 60 km ilerler. Karşıdan gelen araç da aradaki mesafeyi azaltır. İki aracın aldığı yolları ayrı ayrı uzun hesaplamak yerine aranın ne kadar hızla kapandığını izleyebiliriz.',
    [['Hız', 'Birim zamanda alınan yol; burada sabit hızın büyüklüğü.'], ['Bağıl hız', 'İki hareketli arasındaki mesafenin değişme hızı.'], ['Birim', 'km/sa ile dakika birlikte kullanılacaksa zaman çevrilmeli.']],
    'Aralarında 300 km olan araçları zaman kaydırıcısıyla ilerlet. Birinin 60, diğerinin 40 km/sa gitmesi arayı saatte kaç km kapatıyor? Karşılaşmadan önce tahmin et.',
    '300 km uzaktaki iki araç birbirine doğru 60 ve 40 km/sa hızlarla gidiyor. Ne zaman karşılaşırlar?',
    [['Aradaki mesafeyi izle', 'Bir saatte soldaki 60, sağdaki 40 km yaklaşır. Aradaki mesafe 100 km azalır.'], ['Toplam arayı kapanma hızına böl', '$t=300/(60+40)=3$ saat. Hızları topluyoruz çünkü ikisi de aynı arayı kapatıyor.'], ['Konumu doğrula', 'İlk araç 180 km, ikinci araç 120 km gider; toplam 300. Karşılaşma orta nokta olmak zorunda değildir.']],
    'Birbirine yaklaşmada hızları topla; aynı yönde yetişmede hızlıdan yavaşı çıkar. Önce iki aracın yönünü çiz, sonra bağıntıyı seç.',
    'Eşit yolları farklı hızlarla giderken ortalama hız, hızların basit ortalaması değildir. Toplam yolu toplam süreye böl.',
    ['Aynı yönde 70 ve 50 km/sa giden araçların arası saatte ne kadar kapanır?', '20 km', '120 km', 'Hızlı araç her saatte diğerinden 20 km fazla gider. 120, zıt yönde yaklaşmanın kapanma hızıdır.'],
    'Eşit mesafeler v₁ ve v₂ hızlarıyla alınırsa ortalama hız 2v₁v₂/(v₁+v₂) olur. Bu kısa yol eşit sürelerde geçerli değildir; eşit sürelerde aritmetik ortalama kullanılır.'),
  'yas-isci-problemleri': lesson(
    'Zaman değişirken ne sabit kalır?',
    'İki kardeşin yaşları 8 ve 14 olsun. Üç yıl sonra ikisi de üçer yaş büyür. Yaşları değişirken aralarındaki 6 yıllık fark korunur. Önce değişmeyeni görmek, gereksiz bilinmeyenleri azaltır.',
    [['Bugünkü yaş', 'Zaman çizgisinde başlangıç kabul ettiğimiz değer.'], ['t yıl sonra', 'Herkesin yaşına aynı t eklenmesi.'], ['İş hızı', 'İşçi sorularında birim zamanda tamamlanan iş payı.']],
    'Zamanı ileri al. İki yaş çubuğunun aynı miktarda uzadığını ve farkın sabit kaldığını izle. Yaş oranının ise neden değiştiğini sayılarla karşılaştır.',
    '8 ve 14 yaşındaki iki kardeş kaç yıl sonra toplam 30 yaşında olur?',
    [['Bugünkü toplamı bul', '8+14=22. Hedef toplam 30 olduğundan toplamda 8 yıllık artış gerekiyor.'], ['Bir yıldaki toplam artışı bul', 'İki kişi de birer yaş büyür; toplam yaş her yıl 2 artar.'], ['Zamanı bul ve doğrula', '8/2=4 yıl. Yaşlar 12 ve 18 olur; toplam 30, aralarındaki fark yine 6.']],
    'Yaş farkı sabittir; yaş oranı genellikle sabit değildir. İşçi sorusunda da süreleri toplama: önce her kişinin bir saatte yaptığı iş payını bul.',
    'Bir işi 6 ve 3 saatte bitiren iki kişi birlikte 9 saatte bitirmez. Saatlik işler 1/6+1/3=1/2; birlikte 2 saatte bitirirler (sabit ve bağımsız verim varsayımıyla).',
    ['Üç kişinin toplam yaşı 5 yılda kaç artar?', '15', '5', 'Her kişi 5 yaş büyür. Üç kişi için toplam artış 3×5=15; geçen süre ise yine 5 yıldır.'],
    'Havuzda dolduran musluk pozitif, boşaltan negatif iş hızıdır. Net hız sıfırsa seviye değişmez; net hız negatifse boş havuzun dolma süresini pozitifmiş gibi hesaplayamazsın.'),
  'grafik-rutin-olmayan': lesson(
    'Resmi değil, değişimi oku',
    'Bir taksi 30 TL açılış ücreti ve kilometre başına 10 TL alıyor. Grafikte başlangıç noktası, eğim ve birimler farklı bilgiler taşır. Görseli bir dekor olarak değil, ücretin nasıl üretildiğinin kaydı olarak okuyacağız.',
    [['Yatay eksen', 'Burada gidilen yol: kilometre.'], ['Dikey eksen', 'Bu yola karşılık gelen ücret: TL.'], ['Eğim', 'Yatayda bir birim ilerlerken dikey değerin ne kadar değiştiği.']],
    'Kilometreyi artır; çizgi üzerindeki noktayı izle. 0 km’de ücretin neden 0 olmadığını, her kilometrede artışın neden aynı kaldığını anlat.',
    'Açılış 30 TL, kilometre 10 TL ise 80 TL ödeyen kişi kaç km gitmiştir?',
    [['Sabit ve değişken kısmı ayır', '30 TL yolu olmasa da ödenecek başlangıç kısmıdır. Kalan ücret yol için alınır.'], ['Yol payını bul', '80−30=50 TL yol ücretidir. Grafikte başlangıç yüksekliğini çıkarmış olduk.'], ['Birim ücrete böl', '50/10=5 km. Kontrol: 30+10×5=80 TL.']],
    'Grafik sorusunda önce eksen adı, birim, başlangıç ve ölçek. Sonra iki nokta arasındaki farkı kullan; eğimi göz kararı değil Δy/Δx ile bul.',
    'Yatay parça her grafikte “durdu” demek değildir. Konum–zamanda konum sabit; hız–zamanda ise hız sabittir. Dikey eksenin ne olduğunu oku.',
    ['Bu tarifede 3 km’den 5 km’ye geçince ücret kaç artar?', '20 TL', '50 TL', 'Fark 2 km; 2×10=20 TL. Açılış ücretini ikinci kez eklemeyiz; toplamlar çıkarılınca sabit kısım yok olur.'],
    'Rutin olmayan sorularda küçük bir örnek oluşturup tabloyla düzen ara. Bulduğun örüntüyü tüm durumlara uygulamadan önce sınırları ve tekrar eden yapıyı gerekçelendir.'),
  'kumeler-temel': lesson(
    'Bir gruba ait olmak ne demek?',
    'Bir kulüpte gitar çalan öğrencileri bir listeye yazalım. Aynı öğrencinin adını iki kez yazmak kulübe yeni kişi eklemez. Kümeler, nesnelerin tekrarını ve sırasını değil üyeliğini takip eder.',
    [['Eleman', 'Kümenin içindeki bir nesne.'], ['Alt küme', 'Bütün elemanları başka bir kümede de bulunan küme.'], ['Boş küme', 'Hiç elemanı olmayan küme; {0} ile aynı değildir.']],
    'A kümesine hangi elemanların gireceğini seç. Bir elemanı çıkardığında alt küme sayısının nasıl değiştiğine bak. Her eleman için “al / alma” olmak üzere iki karar vardır.',
    'A={a,b,c} kümesinin kaç alt kümesi vardır?',
    [['İlk eleman için iki seçenek düşün', 'a alt kümede bulunabilir veya bulunmayabilir. Bunlar iki ayrı durum.'], ['Diğer elemanlarda aynı kararı ver', 'b için iki, c için iki seçenek. Bağımsız kararlar olduğundan 2×2×2=8.'], ['Uç durumları unutma', 'Hiçbirini seçmemek boş kümeyi, hepsini seçmek A’nın kendisini verir. İkisi de alt kümedir.']],
    'n farklı eleman → 2ⁿ alt küme. Belirli bir eleman mutlaka bulunacaksa onun kararı sabitlenir; geriye n−1 serbest seçim kalır.',
    'a∈A bir eleman ilişkisi; {a}⊆A bir küme ilişkisidir. Süslü parantez sayının veya harfin rolünü değiştirir.',
    ['4 elemanlı kümenin kaç alt kümesi vardır?', '16', '8', 'Her eleman için iki bağımsız karar: 2⁴=16. Bir eleman daha eklemek alt küme sayısını iki katına çıkarır.'],
    'Bir küme içinde {a,b} gibi başka bir küme tek eleman olabilir. Eleman sayarken dış parantezin içindeki nesneleri say; içteki nesneleri izinsiz düzleştirme.'),
  'kume-islemleri': lesson(
    'Ortak kişiyi iki kez sayma',
    'Sınıfta hem müzik hem spor kulübüne giden öğrenciler olabilir. İki kulübün listelerini birleştirirken bu öğrenciler iki listede de görünür, ama sınıfta iki kişi olmazlar. Kesişim düzeltmesi bu çift sayımı giderir.',
    [['Birleşim', 'A’da veya B’de olanlar; ikisinde olanlar da dâhil.'], ['Kesişim', 'Hem A’da hem B’de olanlar.'], ['Fark', 'A’da olup B’de olmayanlar; A−B.']],
    'Şekilde birleşim, kesişim ve fark seçeneklerini sırayla seç. Ortadaki kişilerin birleşimde yalnız bir kez sayıldığını izle.',
    'Müzikte 12, sporda 10, ikisinde birden 4 öğrenci varsa en az bir kulüpte kaç kişi var?',
    [['İlk iki sayıyı topla', '12+10=22 liste kaydı. Ancak bu henüz farklı kişi sayısı değil.'], ['Ortakların ikinci kopyasını çıkar', '4 kişi iki kez sayıldı. Her biri bir kez kalacak şekilde 4 çıkar: 22−4=18.'], ['Bölgeleri ayrı sayarak doğrula', 'Yalnız müzik 8, ortak 4, yalnız spor 6. Toplam 8+4+6=18.']],
    'İki kümeli problemlerde önce ortak bölgeyi yaz. “Yalnız”, “en az bir”, “hiçbiri” ifadelerini şekil üzerinde işaretlemek denklem hatalarını azaltır.',
    '“A veya B” birleşimdir; ortak bölgeyi dışlamaz. “Yalnız birinde” denirse ortak bölge alınmaz.',
    ['A’da 7, B’de 5, ortak 2 kişi varsa birleşim?', '10', '12', '7+5−2=10. 12 iki ortak kişinin ikinci kopyalarını da içerir.'],
    'Tümleme için evrensel küme bilinmelidir. “Hiçbiri”, evrensel kümeden birleşimi çıkarmaktır. Evrensel kümenin dışındaki nesneleri hesaba katma.'),
  'fonksiyon-kavrami': lesson(
    'Girdi girer, tek çıktı çıkar',
    'Bir ücret makinesi girilen saat sayısını alıp toplam fiyatı hesaplıyor. Aynı girdi aynı kuralla tek sonuç üretir. Fonksiyon, bu giriş–çıkış ilişkisinin adıdır; mutlaka karmaşık bir formül olması gerekmez.',
    [['Girdi (x)', 'İşleme verilen değer.'], ['f(x)', 'f kuralının x girdisinden ürettiği çıktı; f×x değildir.'], ['Tanım kümesi', 'Makinenin kabul ettiği girdiler.']],
    'Girdiyi değiştir. Makine önce ikiyle çarpsın, sonra 3 eklesin. Her kutunun yaptığı işlemle formüldeki parçayı eşleştir.',
    '$f(x)=2x+3$ için $f(4)$ kaçtır?',
    [['Parantezin görevini oku', 'f(4), x’in yerine 4 girildiğinde oluşan sonucu sorar. f ile 4’ü çarpmıyoruz.'], ['Kuralı girdiye uygula', '4 → ikiyle çarp → 8 → üç ekle → 11.'], ['Sonucu doğru adlandır', 'f(4)=11. Girdi 4, çıktı 11; bunlar aynı büyüklük olmak zorunda değildir.']],
    'f(ax+b) verilen soruda önce parantezin içini istenen girdiye eşitle. f(5) aranıyorsa ax+b=5 çözmek çoğu kez tüm fonksiyonu bulmaktan kısadır.',
    'İki farklı girdinin aynı çıktıyı vermesi fonksiyon olmayı bozmaz. Bir girdinin iki farklı çıktıya gitmesi bozar.',
    ['f(x)=2x+3 ise f(−1)?', '1', '−5', 'x yerine parantezle −1 yaz: 2×(−1)+3=1. +3 işlemi de uygulanmalıdır.'],
    'Bire bir fonksiyonda farklı girdiler farklı çıktılar verir. Örten fonksiyonda hedef kümede açıkta eleman kalmaz. Bunlar fonksiyon olmanın kendisinden daha güçlü, ayrı şartlardır.'),
  'bileske-ters': lesson(
    'Makinelerin sırası sonucu değiştirir',
    'Bir fotoğrafı önce küçültüp sonra kenarına çerçeve eklemekle, önce çerçeve ekleyip sonra hepsini küçültmek aynı sonucu vermez. Fonksiyonların bileşkesi de işlem sırasını korur. Ters fonksiyon ise yapılanları geriye doğru geri alır.',
    [['Bileşke', 'Bir fonksiyonun çıktısını diğerine girdi yapmak.'], ['f(g(x))', 'Önce içteki g, sonra dıştaki f çalışır.'], ['Ters fonksiyon', 'Çıktıdan ilk girdiye döndüren kural; varlığı için uygun bire bir/örten yapı gerekir.']],
    'Girdiyi iki makineden geçir; sırayı değiştir. Aynı başlangıç sayısının neden farklı çıktılar verdiğini her ara değerde izle.',
    '$f(x)=2x$, $g(x)=x+3$ ise $f(g(4))$ kaçtır?',
    [['İçten başla', 'Önce g(4)=4+3=7. f henüz çalışmadı.'], ['Ara sonucu dıştaki makineye ver', 'f(7)=2×7=14. Bu nedenle f(g(4))=14.'], ['Sıranın önemini kontrol et', 'Ters sırada g(f(4))=g(8)=11. 14 ile 11 farklı; bileşke genellikle değişme özelliğine sahip değildir.']],
    'İç içe fonksiyonlarda en iç parantezden dışarı ilerle ve ara sonucu yaz. Tersini ararken işlem sırasını da ters çevir.',
    'f⁻¹(x), 1/f(x) demek değildir. İlki ters fonksiyon, ikincisi çıktının çarpmaya göre tersidir.',
    ['f(x)=2x+3 makinesinden 11 çıktı. Başlangıç girdisi?', '4', '7', 'Son işlemi geri al: 11−3=8. Sonra ilk işlemi geri al: 8/2=4.'],
    'Ters fonksiyonun grafiği y=x doğrusuna göre yansır; (a,b) noktası (b,a) olur. Bu yüzden tanım ve görüntü kümelerinin rolleri yer değiştirir.'),
  'fonksiyon-grafikleri': lesson(
    'Her nokta bir soru–cevap çifti',
    'Bir taksi tarifesiyle farklı kilometrelerin ücretlerini eşleştirip noktalar çizdiğinde bir grafik elde edersin. Grafik, formüldeki bütün hesapları bir arada görmeye yarar; bir noktadaki x girdi, y çıktıdır.',
    [['(x,y)', 'Önce yatay, sonra dikey konumu söyler.'], ['f(a)', 'Grafikte x=a hizasındaki noktanın yüksekliği.'], ['Kök', 'Grafiğin y=0 olduğu girdi; x ekseniyle kesişim.']],
    'x’i kaydır ve işaretli noktanın grafikteki yerini izle. f(x)=2x+1 için x bir artınca çıktı kaç artıyor? x=0 noktası neden orijinde değil?',
    '$y=2x+1$ grafiğinde x=2 iken y kaçtır?',
    [['Yatay konumu seç', 'x=2, grafikte yatay eksendeki 2 hizasıdır. Buradan eğriye kadar dikey ilerle.'], ['Yüksekliği hesapla', 'y=2×2+1=5. İşaretleyeceğimiz nokta (2,5).'], ['Eğim ve başlangıcı ayır', '1 başlangıç yüksekliği; 2, her bir x artışına karşılık gelen y artışıdır.']],
    'f(a) sorusu: a’dan dikey git, yüksekliği oku. f(x)=b sorusu: b yüksekliğinde yatay git, bütün kesişimlerin x değerlerini oku.',
    'İçi boş nokta o parçanın o noktayı içermediğini gösterir. Aynı x hizasında dolu bir nokta varsa fonksiyonun değeri o dolu noktadan okunur.',
    ['y=2x+1 doğrusu y eksenini nerede keser?', '(0,1)', '(1,0)', 'Y ekseninde x=0’dır; y=1. (1,0), x=1 girdisinden sıfır çıktığı anlamına gelirdi.'],
    'f(x−a), grafiği a>0 için sağa kaydırır. Çünkü eski bir girdiyi aynı çıktıya ulaştırmak için yeni x’in a kadar büyük olması gerekir; parantez içindeki işaretin ters yön göstermesi bundan kaynaklanır.'),
  'polinom-islemleri': lesson(
    'Aynı tür parçaları birleştir',
    'Bir zemini kare paneller, uzun şeritler ve küçük birim karolarla kapladığını düşün. Karelerle şeritleri tek türmüş gibi sayamazsın. Polinomlarda da x², x ve sabit terimler ayrı tür katkılardır.',
    [['Terim', 'Toplama veya çıkarma ile ayrılan parça.'], ['Katsayı', 'Bir türden kaç tane olduğunu belirten sayı.'], ['Derece', 'Sıfır olmayan terimler içindeki en büyük değişken üssü.']],
    'x uzunluğunu değiştir. x²’lik karenin alanı ile x’lik şeridin büyümesini karşılaştır. x iki katına çıkınca hangi parça dört katına çıkar?',
    '$(2x^2+3x+1)+(x^2-2x+4)$ nasıl toplanır?',
    [['Terimleri türlerine göre eşleştir', 'x² terimleri kendi arasında, x terimleri kendi arasında, sabitler kendi arasında toplanır.'], ['Katsayıları topla', '(2+1)x²+(3−2)x+(1+4)=3x²+x+5. Üsler toplanmaz; aynı tür parçaların sayıları toplanır.'], ['Bir değerle hesap kontrolü yap', 'x=1 için ilk ifade 6, ikinci 3; toplam 9. Yeni ifade 3+1+5=9. Bu kontrol bir hesap hatasını yakalayabilir; tek başına özdeşlik kanıtı değildir.']],
    'Katsayılar toplamı için P(1), sabit terim için P(0) hesapla. Tüm açılımı yapmak yerine sorulan değeri doğrudan yerine koy.',
    'Polinomda değişkenin üsleri negatif olmayan tam sayılardır. 1/x=x⁻¹ ve √x=x^(1/2), x’e göre polinom terimi değildir.',
    ['P(x)=3x²+x+5 için katsayılar toplamı?', '9', '5', 'x=1 yaz: 3+1+5=9. 5 yalnız sabit terimdir ve P(0) ile bulunur.'],
    'P(x)’in x−a ile bölümünden kalan P(a)’dır. Bölme eşitliğinde x=a yazınca böleni içeren çarpım sıfır olur; kalanı uzun bölme yapmadan buluruz.'),
  'carpanlara-ayirma': lesson(
    'Aynı alanı iki biçimde say',
    'Bir bahçenin iki yanına b genişliğinde şerit eklediğinde, büyüyen kare yalnız eski kare ve köşedeki küçük kareden oluşmaz. İki yan dikdörtgen de vardır. Özdeşlikteki 2ab, bu iki gerçek parçayı anlatır.',
    [['Çarpan', 'Çarpım biçimindeki ifadenin parçalarından biri.'], ['Özdeşlik', 'Uygun bütün değerlerde doğru olan eşitlik.'], ['Ortak çarpan', 'Her terimde bulunan çarpan; dışarı alınabilir.']],
    'a ve b uzunluklarını değiştir. Büyük karenin dört parçasını takip et: a², ab, ab ve b². İki dikdörtgen kaybolursa alandan ne eksilir?',
    '$(x+3)^2$ neden $x^2+9$ değildir?',
    [['Bir kenarı x+3 olan kareyi çiz', 'Her kenarı x ve 3 olarak ayırınca dört bölge oluşur.'], ['Bölgelerin alanlarını hesapla', 'x²’lik kare; iki tane 3x’lik dikdörtgen; 9’luk küçük kare.'], ['Alanları topla', '$x^2+3x+3x+9=x^2+6x+9$. Çapraz iki alan toplam 6x katkı yapar.']],
    'Önce ortak çarpanı ara; sonra özdeşlik biçimini tanı. x²−9 gibi iki kare farkında doğrudan (x−3)(x+3) kullanabilirsin.',
    'Toplamdaki terimler sadeleşmez; yalnız çarpanlar sadeleşir. (x+3)/x ifadesinde x’leri çizmek geçerli bir işlem değildir.',
    ['(x+2)² açılımındaki x terimi?', '4x', '2x', 'İki çapraz dikdörtgenin her biri 2x; toplam 4x. Sonuç x²+4x+4.'],
    'Görsel alan modeli pozitif uzunluklarla kuruludur; cebirsel özdeşlik dağılım özelliğiyle bütün gerçek x değerlerine genişler. Sadeleştirmede ilk paydanın sıfır olamayacağı koşulu sonuçta da korunur.'),
  'sayma-permutasyon': lesson(
    'Her seçim yeni yollar açar',
    '3 tişört ve 2 pantolonla kaç farklı kıyafet oluşturabilirsin? Her tişört için iki pantolon seçeneği vardır. Bütün seçenekleri sistemli listelemek, çarpma kuralının nedenini gösterir.',
    [['Çarpma ilkesi', 'Birlikte tamamlanan ardışık seçimlerin sayılarını çarpmak.'], ['Permütasyon', 'Seçilen nesneleri sırasını önemseyerek dizmek.'], ['Faktöriyel', 'n!=n×(n−1)×…×1; kalan seçeneklerin çarpımı.']],
    'Tişört ve pantolon sayılarını değiştir. Her hücre bir eşleşme; bir yeni tişört ekleyince neden pantolon sayısı kadar yeni kıyafet oluşuyor?',
    '4 kişi arasından bir başkan ve bir yardımcı kaç farklı şekilde seçilir?',
    [['İlk görevi doldur', 'Başkan için 4 aday var. Bir kişiyi başkan seçtiğimizi düşünelim.'], ['Kalan seçenekleri say', 'Aynı kişi iki görevi almayacağı için yardımcı için 3 aday kalır.'], ['Seçimleri birleştir', '4×3=12. Ayşe başkan, Can yardımcı ile Can başkan, Ayşe yardımcı farklı görev dağılımlarıdır.']],
    'Önce boş yerleri çiz. Her yere o anda kaç seçenek kaldığını yaz. “Tekrar yok” koşulu seçenekleri azaltır; tekrar varsa azaltmaz.',
    'Çarpma ile toplama farklıdır: bir tişört VE bir pantolon için çarp; birbirini dışlayan alternatif yollardan BİRİ seçilecekse sayıları topla.',
    ['5 kişiden başkan ve yardımcı seçme sayısı?', '20', '10', 'Görevler farklı: 5×4=20. 10, görevsiz iki kişilik grup sayısı olurdu.'],
    'Yan yana durması istenen nesneleri önce tek blok say; sonra bloğun iç sıralamalarını çarp. Dairesel dizilişte döndürmeyle aynı olan düzenleri tekrar saymamak gerekir; hangi simetrilerin eş sayıldığı sorudan okunur.'),
  'kombinasyon': lesson(
    'Grup aynıysa sırayı tekrar sayma',
    'Bir proje ekibinde Ayşe–Can ile Can–Ayşe aynı iki kişidir; görev sırası yoktur. Permütasyon bu iki yazılışı ayrı sayar. Kombinasyon, aynı grubun farklı sıralamalarını tekleştirir.',
    [['Kombinasyon', 'Sıra önemsenmeden seçim.'], ['C(n,r)', 'n farklı nesneden r tanesini seçmenin sayısı.'], ['Tekrar sayım', 'Aynı sonucu farklı sıralarla birden fazla saymak.']],
    'Kişi sayısını değiştir. Eşleşme karelerinde AB ve BA’nın aynı gruba gittiğini gör. Kendisiyle eşleşme neden çıkarılıyor?',
    '4 kişiden iki kişilik ekip kaç şekilde seçilir?',
    [['Önce sıralı seçimi say', 'İlk kişi için 4, ikinci için 3 seçenek: 12 sıralı liste.'], ['Her grubun tekrarını bul', 'AB ve BA aynı ekip. Her iki kişilik ekip 2!=2 kez sayıldı.'], ['Tekrara böl', '12/2=6 ekip. Gruplar AB, AC, AD, BC, BD, CD olarak tek tek de listelenebilir.']],
    '“Seç, ekip kur” ve görev ayrımı yok → kombinasyon. “Sırala, başkan–yardımcı” → permütasyon. C(n,r)=C(n,n−r) ile küçük olan seçimi hesapla.',
    'Her sayma sorusunu n! ile çözme. Nesnelerin farklı olup olmadığı, tekrar izni ve sıranın sonucu değiştirip değiştirmediği belirleyicidir.',
    ['5 kişiden iki kişilik görevsiz ekip sayısı?', '10', '20', '5×4=20 sıralı seçim. Her grup iki kez sayıldığı için 20/2=10.'],
    'C(n,r)=C(n−1,r)+C(n−1,r−1): belirli bir kişinin olmadığı ekipler ile olduğu ekipleri ayrı say. Pascal üçgeninin toplama kuralı bu iki ayrık durumdan gelir.'),
  'binom': lesson(
    'Katsayılar, seçim yollarını sayar',
    'Üç günlük bir planın her gününde A veya B etkinliği seçebilirsin. Tam iki gün A olan planlar AAB, ABA, BAA’dır. Bir açılımdaki 3 katsayısı, aynı çarpımı oluşturan bu farklı seçim yollarını sayar.',
    [['Binom', 'İki terimli ifade; örneğin a+b.'], ['Açılım', 'Parantezlerin çarpımını terimlerin toplamı olarak yazmak.'], ['Katsayı', 'Aynı tür terimin kaç yoldan oluştuğu.']],
    'Kaç parantez olduğunu değiştir; her A/B seçim yolunu izle. Aynı sayıda B içeren yolları grupladığında Pascal katsayıları görünür.',
    '$(a+b)^3$ açılımında $a^2b$ teriminin katsayısı neden 3?',
    [['Üç parantezi düşün', '(a+b)(a+b)(a+b). Her parantezden bir terim seçip çarpıyoruz.'], ['İstenen terimi oluşturan yolları bul', 'İki parantezden a, birinden b seçilmeli. b ilk, ikinci veya üçüncü parantezden gelebilir.'], ['Aynı terimleri birleştir', 'Üç yol da a²b verir: aab, aba, baa. Toplam 3a²b; katsayı C(3,1)=3.']],
    'İstenen terimde kaç kez ikinci terimin seçileceğini belirle. Genel terimde önce x’in üssünü hedefe eşitle; sonra yalnız o katsayıyı hesapla.',
    'Terim sırası ile seçilen ikinci terim sayısı aynı değildir. k=0 ilk terimdir; k seçimi (k+1). terimi verir.',
    ['(a+b)⁴ içinde a³b katsayısı?', '4', '3', 'b dört parantezden herhangi birinden seçilebilir: 4 yol. Üç tane a olması katsayının 3 olduğu anlamına gelmez.'],
    'Katsayılar toplamını bulmak için değişkene 1 ver. (2x−1)ⁿ için toplam (2−1)ⁿ=1 olur; tüm açılımı yazman gerekmez. Bu, sabit terimi bulma yöntemiyle karıştırılmamalı.'),
  'olasilik': lesson(
    'Önce mümkün sonuçları görünür yap',
    'Adil bir zarın altı yüzünden her biri eşit olasılıkla gelir. “Çift gelmesi” bir tek sonuç değildir; 2, 4 ve 6’yı içerir. Olasılık, istediğimiz sonuçların bütün mümkün sonuçlar içindeki payıdır.',
    [['Örnek uzay', 'Deneyin bütün mümkün sonuçları.'], ['Olay', 'İlgilendiğimiz sonuçların oluşturduğu alt küme.'], ['Eş olasılık', 'Her temel sonucun gerçekleşme ihtimalinin aynı olması.']],
    'İstenen en küçük zar değerini değiştir. Vurgulanan yüzler istenenler, bütün altı yüz mümkün sonuçlar. Pay değişirken paydanın neden aynı kaldığını izle.',
    'Adil bir zar atıldığında sonucun 4’ten büyük olma olasılığı?',
    [['Bütün sonuçları listele', '1, 2, 3, 4, 5, 6. Altı eş olasılıklı sonuç vardır.'], ['Koşulu sağlayanları seç', '4’ten büyük olanlar 5 ve 6: iki sonuç. 4 dâhil değildir.'], ['İstenen/bütün oranını kur', '2/6=1/3. Sonuç 0 ile 1 arasında; yarıdan az yüz uygun olduğu için yarıdan küçüktür.']],
    '“En az bir” sorusunda karşıt olayı saymak daha kısa olabilir: 1−P(hiçbiri). Önce bütün sonuçların gerçekten eş olasılıklı olup olmadığını kontrol et.',
    'İki zarın toplamları 2,3,…,12 eş olasılıklı değildir. Örneğin 7 altı farklı yolla, 2 yalnız (1,1) ile oluşur. Temel sonuçları doğru seç.',
    ['Adil zarda 3’ten büyük sonuç olasılığı?', '1/2', '1/3', '4,5,6 olmak üzere 3 uygun yüz; 3/6=1/2. “Büyük” koşulunu 3’ü almadan uygula.'],
    'A veya B için olasılıkları toplarken ortak bölge iki kez sayılır. Genel kural P(A∪B)=P(A)+P(B)−P(A∩B). Yalnız ayrık olaylarda son terim sıfırdır.'),
  'kosullu-olasilik': lesson(
    'Yeni bilgi, saydığın dünyayı küçültür',
    'Zarın çift geldiğini öğrendin ama hangi sayı olduğunu bilmiyorsun. Artık 1,3,5 mümkün değildir. Aynı zar hakkında yeni bilgi, olasılığın paydasını değiştirir. Koşullu olasılık bu daraltılmış dünya içinde hesap yapar.',
    [['Koşul', 'Gerçekleştiğini bildiğimiz bilgi.'], ['P(A|B)', 'B olduğu bilinirken A’nın olasılığı; dik çizgi “koşuluyla” diye okunur.'], ['Bağımsızlık', 'B bilgisi A’nın olasılığını değiştirmiyorsa olaylar bağımsızdır.']],
    '“Çift geldi” koşulunu aç. Paydanın altı yüzden üç yüze indiğini izle. İstenen olay hâlâ “4’ten büyük”; hem koşulu hem isteği sağlayan hangi yüz kalıyor?',
    'Zarın çift geldiği biliniyorsa 4’ten büyük olma olasılığı?',
    [['Koşulu önce uygula', 'Yeni mümkün sonuçlar {2,4,6}. Artık altı sonuç üzerinden hesap yapmıyoruz.'], ['Bu grubun içindeki isteği seç', 'Bu üç sayı içinde 4’ten büyük olan yalnız 6.'], ['Yeni bütüne göre oranla', '1/3. Koşulsuz olasılık 2/6 idi; burada sayılan olaylar farklı olsa da sayısal sonuç tesadüfen aynı.']],
    '“Bilindiğine göre” ifadesinden sonra önce koşul kümesini çiz. Payda koşulu sağlayanlar; pay hem koşulu hem isteği sağlayanlardır.',
    '“Geri koymadan” çekilişte ikinci adımın toplamı değişir. İlk adımın olasılığını ikinciye aynen kopyalama.',
    ['Zar çift geldiyse 2 gelme olasılığı?', '1/3', '1/6', 'Mümkün yüzler artık 2,4,6. 2 bunlardan biri: 1/3. Altılı paydayı kullanmak verilen bilgiyi yok sayar.'],
    'Ayrık ve bağımsız aynı şey değildir. Pozitif olasılıklı ayrık olaylardan biri gerçekleşince diğeri imkânsız olur; bu durum bağımsızlık değildir. Koşulun olasılığı sıfırsa standart koşullu oran tanımlanmaz.'),
  'onermeler': lesson(
    'Cümleleri doğrulukla birleştir',
    'Bir etkinliğe giriş için “biletin var VE yaşın uygun” denebilir. Biri eksikse giriş yoktur. “Öğrenci VEYA öğretmen” koşulunda ise bunlardan en az birinin doğru olması yeterlidir. Bağlaçlar, karar kurallarıdır.',
    [['Önerme', 'Doğru veya yanlış değeri taşıyan yargı cümlesi.'], ['Ve (∧)', 'İki taraf da doğruysa doğru.'], ['Veya (∨)', 'En az bir taraf doğruysa doğru; ikisi de doğru olabilir.']],
    'p ve q anahtarlarını açıp kapat. “Ve” ile “veya” sonuçlarını aynı anda karşılaştır. Özellikle ikisi de doğruyken “veya”nın ne verdiğine bak.',
    'p doğru, q yanlış ise (p∧q)∨p nedir?',
    [['İçteki bağlacı değerlendir', 'p∧q için iki taraf da doğru olmalı. q yanlış olduğu için sonuç yanlış.'], ['Dış bağlacı uygula', 'Yanlış ∨ doğru ifadesinde en az biri doğru: sonuç doğru.'], ['Kuralı gündelik dille kur', '“Hem koşul 1 hem koşul 2, veya yalnız koşul 1” denildiğinde koşul 1 doğru olması yeterlidir.']],
    'Önce parantez içi, sonra dış bağlaç. Karmaşık önermede p ve q için 0/1 yazmak uzun cümleleri kısa bir karar hesabına dönüştürür.',
    '“Veya” ile “ya da” aynı değildir. Mantıkta ya da yalnız bir taraf doğruysa doğru; iki taraf birden doğruysa yanlıştır.',
    ['p ve q ikisi de doğruysa p∨q?', 'Doğru', 'Yanlış', 'Veya en az bir doğru ister; iki doğru da bunu sağlar. Yalnız bir doğru şartı “ya da” içindir.'],
    'De Morgan: “İkisinin de doğru olması değil” demek “en az biri yanlış” demektir. Bu nedenle ¬(p∧q)=¬p∨¬q; değilleme bağlacı değiştirir ve her parçayı değiller.'),
  'kosullu-onerme': lesson(
    'Bir söz ne zaman bozulur?',
    '“Ödevi bitirirsen oyun oynayabilirsin” biçimindeki bir koşullu sözü düşün. Ödev bitmiş olduğu hâlde izin yoksa söz bozulur. Ödev bitmemişse bu söz o durum için bir sonuç vaat etmemiştir. Matematikte p⇒q tam bu doğruluk düzenini kullanır.',
    [['p⇒q', 'p doğruysa q’nun da doğru olmasını isteyen önerme.'], ['Karşıt ters', '¬q⇒¬p; ilk koşulluyla aynı doğruluk değerleri.'], ['Çift yönlü (⇔)', 'İki yönün de geçerli olması; doğruluk değerleri eşit olmalı.']],
    'Ön koşul p ve sonuç q’yu değiştir. Dört olasılıkta sözün yalnız p doğru, q yanlış iken bozulduğunu gör.',
    '“Bir sayı 4’e bölünüyorsa çifttir.” önermesini değerlendirelim.',
    [['p ve q’yu ayır', 'p: 4’e bölünür. q: çifttir. Önermenin yanlış olması için p doğruyken q yanlış olmalı.'], ['Böyle bir karşı örnek ara', '4’e bölünen sayı 4k=2(2k) biçimindedir; mutlaka çifttir. Bu tür bir karşı örnek yoktur.'], ['Ters yönle karıştırma', '“Çiftse 4’e bölünür” yanlıştır: 6 çifttir ama 4’e bölünmez. Yönün değişmesi iddiayı değiştirir.']],
    'p⇒q yanlış deniyorsa doğrudan p=1 ve q=0 yaz. Karşıt ters eşdeğerdir; yalnız yer değiştirmek eşdeğerlik sağlamaz.',
    'Koşullu önerme nedensellik kanıtı değildir. Matematiksel doğruluk tablosu, iki ifadenin gerçek hayatta birbirine neden olduğunu söylemez.',
    ['p⇒q ne zaman yanlıştır?', 'p doğru, q yanlışken', 'p yanlış, q doğruyken', 'Koşul gerçekleşmişken vaat edilen sonuç gerçekleşmezse önerme yanlış olur.'],
    'p⇒q, ¬p∨q ile eşdeğerdir. “Her x için” iddiasını çürütmek için tek karşı örnek yeter; “en az bir x var” iddiasını kanıtlamak için tek uygun örnek yeter.'),
  'merkezi-egilim': lesson(
    'Ortalama bir denge noktasıdır',
    'Dört arkadaşın kitap sayıları 2,4,4,6 olsun. Kitapları eşit dağıtsalar herkes 4 kitap alır. Aritmetik ortalama, eşitleme sonucu kişi başına düşen miktardır; herkesin başlangıçta bu miktara sahip olduğunu söylemez.',
    [['Ortalama', 'Toplamın veri sayısına bölümü.'], ['Ortanca (medyan)', 'Sıralanmış verinin ortasındaki değer; çift sayıda veri varsa ortadaki ikisinin ortalaması.'], ['Tepe değer (mod)', 'En sık tekrar eden değer.']],
    'En büyük değeri artır. Ortalama çizgisinin hareket ettiğini, ortancanın ise aynı kalabildiğini izle. Tek bir uç değerin temsil gücünü nasıl etkilediğini düşün.',
    '2,4,4,6 verilerinin ortalaması, ortancası ve modu nedir?',
    [['Ortalama için bütünü paylaştır', 'Toplam 16; 4 veri var. 16/4=4.'], ['Ortanca için sırayı kontrol et', 'Veriler sıralı. Ortadaki 4 ve 4’ün ortalaması 4.'], ['Tekrarı say', '4 iki kez, diğerleri birer kez geçiyor; mod 4. Bu örnekte üçünün eşit olması her zaman eşit oldukları anlamına gelmez.']],
    'Ortalamada önce toplam=ortalama×adet bağıntısını yaz. İki grubun ortalamasını birleştirirken grup büyüklüklerini ağırlık olarak kullan.',
    'Ortanca bulunmadan veriler sıralanmalı. Grup sayıları eşit değilse grup ortalamalarının basit ortalaması genel ortalama değildir.',
    ['2,4,4,30 verilerinin ortancası?', '4', '10', 'Ortadaki iki değer 4 ve 4; ortanca 4. 10 aritmetik ortalamadır: 40/4.'],
    'Bütün verilere aynı c eklenirse ortalama ve ortanca c artar; açıklık ve standart sapma değişmez. Verileri k ile çarpmak yayılım ölçülerini |k| katına çıkarır.'),
  'veri-grafikleri': lesson(
    'Açı, bütünün bir payıdır',
    'Bir sınıfın spor tercihlerini daire grafiğinde gösterdiğimizde herkes eş büyüklükte bir pay temsil eder. Dilim açısı öğrenci sayısının kendisi değildir; bütün sınıfa göre oranını görselleştirir.',
    [['Tam daire', '360°; bütün verinin tamamı.'], ['Dilim açısı', 'Kategorinin bütün içindeki oranı×360°.'], ['Frekans', 'Bir kategoride kaç gözlem bulunduğu.']],
    'Seçilen grubun yüzdesini değiştir. Sayı, yüzde ve açı birlikte değişsin. %25’in neden 90° olduğunu bütünün dörtte biri üzerinden anlat.',
    '120 kişilik grupta 90°’lik dilim kaç kişiyi gösterir?',
    [['Açıyı bütüne oranla', '90/360=1/4. Dilim bütün dairenin çeyreği.'], ['Aynı payı kişi sayısına uygula', '120×1/4=30 kişi. Açı oranı ile kişi oranı aynıdır.'], ['Toplamla kontrol et', 'Dört tane böyle dilim olsaydı 4×30=120 kişi olurdu; bütün sınıfı tamamlar.']],
    '90°=1/4, 120°=1/3, 180°=1/2 gibi payları tanımak hesabı hızlandırır. Yüzde→açı dönüşümünde yüzdeyi 3,6 ile çarp.',
    'Farklı toplamlı iki dairede aynı açı aynı kişi sayısı demek değildir. Önce her grafiğin toplamını oku.',
    ['60 kişilik grubun 120°’lik dilimindeki kişi sayısı?', '20', '120', '120°/360°=1/3; 60/3=20 kişi. Derece birimini kişi sayısıyla karıştırma.'],
    'Histogramda bitişik sütunlar sayısal aralıkları temsil eder. Aralık genişlikleri eşit değilse frekansın yükseklikle mi alanla mı kodlandığını eksen etiketinden kontrol etmek gerekir.'),
};
